var sb = new System.Text.StringBuilder();
var searches = UnityEngine.Object.FindObjectsByType<RaySearch>(FindObjectsInactive.Include, FindObjectsSortMode.None);
foreach (var s in searches)
{
    // Pick a ray origin/direction that hits this wall
    Vector3 origin;
    Vector3 dir;
    if (s.gameObject.name == "EdgeSearch")
    {
        // Use the EdgeSearch transform's forward direction as a probe
        origin = s.transform.position + Vector3.up * 0.5f;
        // Probe direction: from EdgeSearch towards its parent center
        var parent = s.transform.parent;
        if (parent != null)
        {
            var pCenter = parent.position;
            dir = (pCenter - origin); dir.y = 0; dir.Normalize();
            if (dir.sqrMagnitude < 0.001f) dir = s.transform.forward;
        }
        else dir = s.transform.forward;
    }
    else
    {
        origin = s.transform.position;
        dir = s.transform.forward;
    }
    s.mergeMode = WallMerge.WallMergeMode.Current;
    s.DoPointsFromPlayer(origin, dir);
    var path = s.transform.parent != null ? s.transform.parent.name : s.gameObject.name;
    sb.AppendLine($"{path} -> meshPoints={s.meshPoints.Count}, cornerPoints={s.cornerPoints.Count}, IsClosedLoop={s.IsClosedLoop}, minCornerAngle={s.minCornerAngleDegrees}");
}
return sb.ToString();
